#ifndef __DYNOMITE_GAMETEXT_H__
#define __DYNOMITE_GAMETEXT_H__

// Most of Dynomite's texts are string properties (properties/default.xml, read with GetString); a few are hard-coded
// in the original's exe (the modes' high-score titles, some labels). port: by the user's decision (2026-10-19) no game
// text is in the repository: the port reads those from the player's own executable, by address, and a mod or language
// pack can replace any of them.
//
// - GameTextTable.inc (generated by games/dynomite/tools/make_gametext.py from tools/gametext_vas.txt) lists each
//   string's address in the game image, its length and a hash: no text.
// - LoadGameTexts() reads Dynomite.exe from the game folder, finds the game image in it (the file may hold more than
//   one PE image; the one whose texts match is used), reads each text at its address and checks length and hash. A
//   text that does not match (another version of the exe) stays empty and is logged.
// - Code names a text by its address in the original: GT(0x004f7594). Overrides: any string property named
//   GT_<8 hex digits> (e.g. <String id="GT_004f7594">...</String> from a mod) replaces the text read from the exe.

#include "Common.h"

namespace Sexy
{

// Reads the texts from the game folder's executable and applies the string-property overrides. Returns
// false when the executable is missing or no text matched (the texts are then empty or overrides only).
bool				LoadGameTexts();
// The text the original keeps at theVA; "" for an address that is not in the table
const SexyString&	GameText(unsigned int theVA);

#define GT(theVA) (::Sexy::GameText(theVA))
#define GTC(theVA) (::Sexy::GameText(theVA).c_str())

}

#endif
